const r = $input.first().json;
let body = r.data ?? r;

if (typeof body === 'string') {
  const s = body.trim();
  try { body = JSON.parse(s); } catch (e) { body = s; }
}

let token;
if (typeof body === 'string') {
  token = body.replace(/^"|"$/g, '');
} else {
  token = body.access_token || body.accessToken || body.token || body.jwt || body.id_token;
}

if (!token || typeof token !== 'string') {
  const keys = typeof body === 'object' && body ? Object.keys(body).slice(0, 20).join(', ') : typeof body;
  throw new Error('Token field not found. Available: ' + keys);
}
return [{ json: { token } }];

const token = $('Extract Token').first().json.token;
const base = 'https://personal.connectapi.garmin.com';
const TOTAL_DAYS = 365;  // always the last 365 days
const WINDOW = 28;
const DAY = 86400000;
const fmt = d => d.toISOString().slice(0, 10);
const today = fmt(new Date());

const endpoints = [
  { name: 'dailysummaries', path: '/usersummary-service/v2/dailysummaries?startDate={start}&endDate={end}', window: 28 },
  { name: 'sleep',          path: '/sleep-service/sleep/dailySleepSummariesByDate?startDate={start}&endDate={end}', window: 31 },
  { name: 'hrv',            path: '/hrv-service/hrv/daily/{start}/{end}' },
  { name: 'fitnessage',     path: '/fitnessage-service/fitnessage/v2/{day}', todayOnly: true },
  { name: 'activities',     path: '/activitylist-service/activities/search/activities?startDate={start}&endDate={end}&limit=99' }
];

const items = [];
for (const e of endpoints) {
  if (e.todayOnly) {
    items.push({ json: { name: e.name, url: base + e.path.split('{day}').join(today), token, day: today, forceDay: true } });
    continue;
  }
  const win = e.window || WINDOW;
  for (let off = 0; off < TOTAL_DAYS; off += win) {
    const end = fmt(new Date(Date.now() - off * DAY));
    const start = fmt(new Date(Date.now() - (Math.min(off + win, TOTAL_DAYS) - 1) * DAY));
    const p = e.path.split('{start}').join(start).split('{end}').join(end);
    items.push({ json: { name: e.name, url: base + p, token } });
  }
}
return items;

const reqs = $('Build Requests').all();
const res = $input.all();
const unwrap = j => {
  let b = (j && j.body !== undefined) ? j.body : j;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
  return b;
};
const expand = b => Array.isArray(b) ? b
  : (b && typeof b === 'object' ? (Object.values(b).find(v => Array.isArray(v)) || [b]) : []);
const obj = x => { if (typeof x === 'string') { try { return JSON.parse(x); } catch (e) { return {}; } } return x || {}; };
const g = (o, path) => path.split('.').reduce((a, k) => (a == null ? undefined : a[k]), o);
const mins = s => (s == null ? undefined : Math.round(s / 60));
const hours = s => (s == null ? undefined : Math.round(s / 360) / 10);

const mappers = {
  dailysummaries: r => {
    const mv = obj(r.movement);
    return {
      steps: g(mv, 'steps.value'),
      steps_goal: g(mv, 'steps.goal'),
      distance_m: g(mv, 'steps.distanceInMeters'),
      floors_up: g(mv, 'floorsAscended.value'),
      calories_resting: g(r, 'calories.burnedResting'),
      calories_active: g(r, 'calories.burnedActive'),
      calories_total: g(r, 'calories.burnedTotal'),
      hr_resting: g(r, 'heartRate.restingValue'),
      hr_min: g(r, 'heartRate.minValue'),
      hr_max: g(r, 'heartRate.maxValue'),
      intensity_moderate: g(r, 'intensityMinutes.moderate'),
      intensity_vigorous: g(r, 'intensityMinutes.vigorous'),
      intensity_goal: g(r, 'intensityMinutes.goal'),
      stress_avg: g(r, 'stress.avgLevel'),
      stress_max: g(r, 'stress.maxLevel'),
      stress_qualifier: g(r, 'stress.qualifier'),
      bb_min: g(r, 'bodyBattery.minValue'),
      bb_max: g(r, 'bodyBattery.maxValue'),
      bb_charged: g(r, 'bodyBattery.chargedValue'),
      bb_drained: g(r, 'bodyBattery.drainedValue'),
      bb_latest: g(r, 'bodyBattery.latestValue'),
      resp_avg: g(r, 'respiration.avgValue'),
      resp_min: g(r, 'respiration.minValue'),
      resp_max: g(r, 'respiration.maxValue'),
      hydration_ml: g(r, 'hydration.consumedInMl'),
      hydration_goal_ml: g(r, 'hydration.goalInMl')
    };
  },
  sleep: r => ({
    sleep_hours: hours(r.sleepTimeSeconds),
    sleep_deep_min: mins(r.deepSleepSeconds),
    sleep_light_min: mins(r.lightSleepSeconds),
    sleep_rem_min: mins(r.remSleepSeconds),
    sleep_awake_min: mins(r.awakeSleepSeconds),
    sleep_score: g(r, 'sleepScores.overall.value'),
    sleep_score_label: g(r, 'sleepScores.overall.qualifierKey'),
    sleep_feedback: r.sleepScoreFeedback,
    sleep_avg_hr: r.avgHeartRate,
    sleep_avg_stress: r.avgSleepStress,
    sleep_resp_avg: r.averageRespirationValue,
    sleep_awake_count: r.awakeCount,
    sleep_need_min: g(r, 'sleepNeed.actual')
  }),
  hrv: r => ({
    hrv_last_night: r.lastNightAvg,
    hrv_weekly_avg: r.weeklyAvg,
    hrv_5min_high: r.lastNight5MinHigh,
    hrv_baseline_low: g(r, 'baseline.balancedLow'),
    hrv_baseline_high: g(r, 'baseline.balancedUpper'),
    hrv_status: r.status
  }),
  fitnessage: r => {
    let s = JSON.stringify(r);
    if (s.length > 45000) s = JSON.stringify({ truncated: true });
    return { fitnessage_raw: s };
  }
};

const rows = {};
let firstError = null;
res.forEach((r, i) => {
  if (!r.json || r.json.error) {
    firstError = firstError || JSON.stringify((r.json || {}).error || 'empty item').slice(0, 300);
    return;
  }
  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  const idx = p && p.item !== undefined ? p.item : i;
  const req = (reqs[idx] || {}).json;
  if (!req || !mappers[req.name]) return;
  const body = unwrap(r.json);
  const recs = req.day ? [body] : expand(body);
  for (const rec of recs) {
    if (!rec || typeof rec !== 'object') continue;
    const d = req.forceDay ? req.day : String(rec.calendarDate || rec.date || '').slice(0, 10);
    if (!d) continue;
    const row = rows[d] || (rows[d] = { Date: d });
    const fields = mappers[req.name](rec);
    for (const [k, v] of Object.entries(fields)) {
      if (v !== undefined && v !== null) row[k] = v;
    }
    row.updated_at = new Date().toISOString();
  }
});
const out = Object.values(rows).map(json => ({ json }));
if (!out.length) throw new Error('No daily rows produced. First error: ' + firstError);
return out;

const reqs = $('Build Requests').all();
const res = $input.all();
const unwrap = j => {
  let b = (j && j.body !== undefined) ? j.body : j;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
  return b;
};
const expand = b => Array.isArray(b) ? b
  : (b && typeof b === 'object' ? (Object.values(b).find(v => Array.isArray(v)) || [b]) : []);
const r1 = x => (x == null ? '' : Math.round(x * 10) / 10);
const r0 = x => (x == null ? '' : Math.round(x));
const mins = x => (x == null ? '' : Math.round(x / 6) / 10);

const out = [];
const seen = new Set();
res.forEach((r, i) => {
  if (!r.json || r.json.error) return;
  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  const idx = p && p.item !== undefined ? p.item : i;
  const req = (reqs[idx] || {}).json;
  if (!req || req.name !== 'activities') return;
  for (const a of expand(unwrap(r.json))) {
    if (!a || typeof a !== 'object' || a.activityId == null) continue;
    const id = String(a.activityId);
    if (seen.has(id)) continue;
    seen.add(id);
    const speed = a.averageSpeed;
    const type = a.activityType && a.activityType.typeKey || '';
    out.push({ json: {
      Date: String(a.startTimeLocal || '').slice(0, 10),
      ActivityID: id,
      start_local: a.startTimeLocal || '',
      name: a.activityName || '',
      type,
      event_type: a.eventType && a.eventType.typeKey || '',
      distance_km: a.distance == null ? '' : Math.round(a.distance / 10) / 100,
      duration_min: mins(a.duration),
      moving_min: mins(a.movingDuration),
      elapsed_min: mins(a.elapsedDuration),
      elevation_gain_m: r0(a.elevationGain),
      avg_speed_kmh: speed == null ? '' : r1(speed * 3.6),
      max_speed_kmh: a.maxSpeed == null ? '' : r1(a.maxSpeed * 3.6),
      pace_sec_per_km: (speed && type.includes('running')) ? Math.round(1000 / speed) : '',
      avg_hr: r0(a.averageHR),
      max_hr: r0(a.maxHR),
      avg_power: r0(a.avgPower),
      norm_power: r0(a.normPower),
      max_power: r0(a.maxPower),
      max_20min_power: r0(a.max20MinPower),
      tss: r1(a.trainingStressScore),
      intensity_factor: a.intensityFactor == null ? '' : Math.round(a.intensityFactor * 100) / 100,
      aerobic_te: r1(a.aerobicTrainingEffect),
      anaerobic_te: r1(a.anaerobicTrainingEffect),
      training_load: r1(a.activityTrainingLoad),
      training_effect_label: a.trainingEffectLabel || '',
      bike_cadence: r0(a.averageBikingCadenceInRevPerMinute),
      run_cadence: r0(a.averageRunningCadenceInStepsPerMinute),
      calories: r0(a.calories),
      power_z1_min: mins(a.powerTimeInZone_1),
      power_z2_min: mins(a.powerTimeInZone_2),
      power_z3_min: mins(a.powerTimeInZone_3),
      power_z4_min: mins(a.powerTimeInZone_4),
      power_z5_min: mins(a.powerTimeInZone_5),
      power_z6_min: mins(a.powerTimeInZone_6),
      power_z7_min: mins(a.powerTimeInZone_7),
      updated_at: new Date().toISOString()
    } });
  }
});
return out;

const reqs = $('Build Requests').all();
const stats = {};
$input.all().forEach((r, i) => {
  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  const idx = p && p.item !== undefined ? p.item : i;
  const name = reqs[idx] ? reqs[idx].json.name : 'unmatched';
  const s = stats[name] || (stats[name] = { name, ok: 0, failed: 0, first_error: '' });
  if (!r.json || r.json.error) {
    s.failed++;
    if (!s.first_error) {
      const e = (r.json || {}).error || {};
      s.first_error = String(e.message || 'empty item').slice(0, 160);
    }
  } else { s.ok++; }
});
return Object.values(stats).map(json => ({ json }));
